mapper.select:

where so.del_flag = '0'

    and so.stock_out_id like concat('%', #{query.stockOutId}, '%')


    and so.warehouse_id = #{query.warehouseId}


    and so.type = #{query.type}


    and so.status = #{query.status}


    and so.batch_no like concat('%', #{query.batchNo}, '%')


    and so.customer like concat('%', #{query.customer}, '%')


    and so.create_time >= #{query.createTimeStart}


    and so.create_time <= #{query.createTimeEnd}

order by so.create_time desc
